CREATE FUNCTION public.pdc_monitor_authenticated_acceptance_scope_704(p_evidence jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,auth,extensions AS $scope$
DECLARE f public.pdc_authenticated_email_acceptance_campaign_fixtures_686%rowtype; r public.pdc_authenticated_email_acceptance_campaign_runs_686%rowtype; i public.ai_email_intake%rowtype; a public.ai_email_attachments%rowtype; o public.pdc_provider_email_observations%rowtype; c public.pdc_authenticated_provider_import_agentic_compatibility_controls_684%rowtype; v public.vehicles%rowtype;
BEGIN
 IF jsonb_typeof(p_evidence)<>'object' OR auth.role()<>'authenticated' OR auth.uid()<>'df7c55d9-6ba0-47f6-ba16-44d6ae2c2a4b'::uuid OR lower(btrim(coalesce(auth.jwt()->>'email','')))<>'sales@broometoyota.com.au' OR p_evidence->>'gateway_instance_id'<>'pdc-monitor-staging-sales-uid509-v1' OR p_evidence->>'provider_uid' !~ '^imap_uid:[0-9]+$' OR substring(p_evidence->>'provider_uid' FROM 10)::bigint<515 THEN RETURN jsonb_build_object('ok',false,'code','acceptance_context_projection_required'); END IF;
 SELECT * INTO f FROM public.pdc_authenticated_email_acceptance_campaign_fixtures_686 WHERE active AND intake_id=nullif(p_evidence->>'intake_id','')::uuid AND source_hash=lower(p_evidence->>'source_hash') AND claim_token=nullif(p_evidence->>'claim_token','')::uuid AND provider_uid=p_evidence->>'provider_uid';
 SELECT * INTO r FROM public.pdc_authenticated_email_acceptance_campaign_runs_686 WHERE run_id=f.run_id AND status='active';
 SELECT * INTO c FROM public.pdc_authenticated_provider_import_agentic_compatibility_controls_684 WHERE singleton AND enabled AND NOT task_enabled AND NOT mailbox_contacted AND NOT uid514_processed AND NOT production_writes;
 SELECT * INTO i FROM public.ai_email_intake WHERE id=f.intake_id AND status='processing' AND locked_by=auth.uid() AND claim_token=f.claim_token AND gateway_instance_id=c.gateway_instance_id AND provider_uid=f.provider_uid AND source_hash=f.source_hash AND coalesce(nullif(btrim(internet_message_id),''),graph_message_id)=f.message_id AND lower(btrim(sender_email))=lower(f.sender) AND recipient_mailbox='pmbcontroller@gmail.com' AND provider_authserv_id='mx.google.com' AND provider_authentication->'gmail_authentication_results'='true'::jsonb;
 SELECT * INTO a FROM public.ai_email_attachments WHERE id=f.attachment_id AND intake_id=f.intake_id AND source_hash=f.attachment_hash AND lower(content_type)='application/pdf' AND text_extraction_status='extracted';
 SELECT * INTO o FROM public.pdc_provider_email_observations WHERE observation_id=f.observation_id AND intake_id=f.intake_id AND attachment_id=f.attachment_id AND parent_source_hash=f.source_hash AND attachment_source_hash=f.attachment_hash AND provider_message_id=f.message_id AND provider_authserv_id='mx.google.com';
 SELECT * INTO v FROM public.vehicles WHERE id=f.vehicle_id;
 IF f.fixture_id IS NULL OR r.run_id IS NULL OR c.actor_id IS NULL OR i.id IS NULL OR a.id IS NULL OR o.observation_id IS NULL OR r.actor_id<>auth.uid() OR r.actor_email<>'sales@broometoyota.com.au' OR r.jwt_role<>'authenticated' OR r.server_application_role<>'importer' OR r.gateway_instance_id<>c.gateway_instance_id OR r.release_name<>'pdc-monitor-staging-m502-2026.08.44' OR r.planner_sha256<>'7e08a00bc099610aa919bb7c3089ef84b91a74bafd69f95fab06bfccfdf67348' OR r.trust_receipt_sha256<>'e3e30ace04e676e34f271b161283b9e4764d462f76428d63826fa3cb153d7227' OR c.actor_id<>auth.uid() OR c.actor_email<>'sales@broometoyota.com.au' OR c.server_application_role<>'importer' OR c.gateway_instance_id<>'pdc-monitor-staging-sales-uid509-v1' OR c.release_name<>'pdc-monitor-staging-m502-2026.08.44' OR c.planner_sha256<>r.planner_sha256 OR c.trust_receipt_sha256<>r.trust_receipt_sha256 OR v.id IS NULL OR v.lifecycle_state<>'active' OR v.deleted_at IS NOT NULL OR v.source_payload->>'test_fixture' IS DISTINCT FROM 'true' OR v.source_payload->>'campaign' IS DISTINCT FROM '686' OR v.source_payload->>'namespace' IS DISTINCT FROM r.namespace OR v.permanent_vehicle_id NOT LIKE 'PDC-ACCEPT-686-%' OR i.subject NOT LIKE 'PDC Acceptance 686 %' OR lower(btrim(i.sender_email)) NOT LIKE 'pdc-acceptance-%@staging.pdc-workshop.example.com' THEN RETURN jsonb_build_object('ok',false,'code','acceptance_context_projection_required'); END IF;
 RETURN jsonb_build_object('ok',true,'code','acceptance_context_scope_verified','fixture_id',f.fixture_id,'run_id',r.run_id,'intake_id',i.id,'vehicle_id',v.id,'claim_token',f.claim_token,'provider_uid',f.provider_uid,'source_hash',f.source_hash,'gateway_instance_id',c.gateway_instance_id,'release_name',r.release_name,'planner_sha256',r.planner_sha256,'trust_receipt_sha256',r.trust_receipt_sha256);
EXCEPTION WHEN others THEN RETURN jsonb_build_object('ok',false,'code','acceptance_context_projection_required');
END $scope$;
REVOKE ALL ON FUNCTION public.pdc_monitor_authenticated_acceptance_scope_704(jsonb) FROM public,anon,authenticated,service_role,pdc_email_monitor;

